import type { ChecklistItem, GearSuggestion } from './types.js'

/** Scout Ten Essentials. Always shown first. Hardcoded on purpose and never generated by the model. */
export const TEN_ESSENTIALS = [
  'Pocketknife',
  'First-aid kit',
  'Extra clothing',
  'Rain gear',
  'Water bottle',
  'Flashlight',
  'Trail food',
  'Matches and fire starters',
  'Sun protection',
  'Map and compass',
] as const

/**
 * Comparison key for duplicate detection: lowercase, punctuation and hyphens become spaces,
 * whitespace is collapsed, and a trailing plural "s" is dropped from each word.
 * "First Aid Kits" and "first-aid kit" share a key; "rain jacket" and "rain gear" do not.
 */
export function normalizeItem(item: string): string {
  return item
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(' ')
    .map((word) => (word.length > 3 && word.endsWith('s') && !word.endsWith('ss') ? word.slice(0, -1) : word))
    .join(' ')
}

/** Ten Essentials first, then the model's additions without duplicates or blanks. */
export function mergeChecklist(additionalGear: GearSuggestion[]): ChecklistItem[] {
  const seen = new Set<string>()
  const checklist: ChecklistItem[] = []

  for (const item of TEN_ESSENTIALS) {
    seen.add(normalizeItem(item))
    checklist.push({ item, essential: true })
  }
  for (const gear of additionalGear) {
    const item = gear.item.trim()
    const key = normalizeItem(item)
    if (!key || seen.has(key)) continue
    seen.add(key)
    checklist.push({ item, why: gear.why.trim(), essential: false })
  }
  return checklist
}
